SELECT sku, product_name, pack_size, flow_type, selling_price_inr, cost_price_inr, units_per_case, case_weight_kg
FROM store.products
WHERE pack_size ILIKE '%5 kg%' OR product_name ILIKE '%atta%';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

SELECT sku, name, pack, flow, price_inr, cost_inr, case_units, case_kg
FROM store.products
WHERE pack ILIKE '%5 kg%' OR name ILIKE '%atta%';

